/*
 * Estilos del contenido de MSG-01.
 *
 * El shell (brand bar, nav, sidebar, VERA) ya existe y no se toca; este módulo
 * cubre solo lo que hay dentro del panel de contenido.
 *
 * Nota de token: el corpus de diseño no trae un blanco puro (#FFFFFF). Las
 * superficies que el HTML aprobado pintaba en blanco se apoyan en
 * var(--bw-surface-mist), el neutro más claro que no compite con el fondo Cold
 * White del panel.
 */

/* ---- Cabecera de pantalla ---- */

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-text-secondary);
  margin: 0 0 4px;
}

.pageTitle {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.pageSubtitle {
  font-size: 14px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
  max-width: 560px;
  margin: 0 0 16px;
}

/* ---- Estado E2EE ---- */

.e2eeStatus {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin: 0 0 14px;
  padding: 6px 10px;
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.e2eeStatus i {
  font-size: 12px;
}

/* ---- Aviso de error ---- */

.errorBanner {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 0 0 12px;
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.errorBanner i {
  flex-shrink: 0;
  font-size: 15px;
  margin-top: 1px;
}

/* ---- Barra de acciones ---- */

.actionsBar {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.searchBox {
  position: relative;
  flex: 1 1 220px;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  background: var(--bw-surface-mist);
  color: var(--bw-input-text);
  font-family: inherit;
  font-size: 13px;
  outline: none;
  transition: border-color 0.15s;
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.newContact {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.primaryButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  cursor: default;
}

.primaryButton:disabled {
  opacity: 0.55;
  cursor: default;
}

.primaryButton i {
  font-size: 15px;
  flex-shrink: 0;
}

/* Motivo visible de que "Nuevo contacto" no se puede pulsar: DIR-01 no se
   entrega en el MVP. */
.scopeNote {
  font-size: 10px;
  line-height: 1.4;
  color: var(--bw-input-placeholder);
}

.pageInfo {
  margin-left: auto;
  align-self: center;
  font-size: 12px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

/* ---- Carga ---- */

.loadingPanel {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  color: var(--bw-text-secondary);
  font-size: 13px;
}

/* ---- Paginación ---- */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  color: var(--bw-ink-steel);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s,
    background-color 0.12s;
}

.pageButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageButton:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.pageControl {
  color: var(--bw-input-placeholder);
}

.pageActive,
.pageActive:hover:not(:disabled) {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

