import { useEffect, useState, type FormEvent, type ReactNode } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  type ThreadSummary,
} from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es la pantalla, no una pieza de presentacion: posee el estado de busqueda y de
 * pagina y pide los hilos a `fetchThreadPage`. El orden lo trae el servidor
 * (último elemento descendente) y `ThreadList` no lo reordena.
 *
 * `now` es inyectable para que los tests no dependan del reloj. Cuando no se
 * pasa, ThreadList/`relativeTime` usan su propio `new Date()` de respaldo.
 */
interface MessagesProps {
  profile: MemberProfile;
  now?: Date | undefined;
  /** La cablea App.tsx (F-118), pero MSG-02 no existe en este alcance: se recibe
   *  y se ignora deliberadamente. */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte lo que lanza PostgREST en texto para humanos.
 *
 * El fallo no siempre es un `Error`: PostgREST puede rechazar con un objeto
 * plano `{ code, message }`. `String(e)` sobre ese objeto da `[object Object]`
 * y `e.message` da `undefined`, así que se leen `code` y `message` cuando
 * existen (F-020 / F-128).
 */
function describeError(error: unknown): string {
  const record = (typeof error === 'object' && error !== null ? error : {}) as Record<
    string,
    unknown
  >;
  const code = typeof record.code === 'string' ? record.code : '';
  const message = typeof record.message === 'string' ? record.message : '';
  if (code || message) return [code, message].filter(Boolean).join(' · ');
  if (error instanceof Error) return error.message;
  return 'Error desconocido';
}

export function Messages(props: MessagesProps) {
  const { profile, now } = props;
  // props.onOpenThread no se usa a propósito: MSG-02 no está en el alcance del
  // MVP, así que abrir un hilo no tiene destino (F-118).

  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);

  const [threads, setThreads] = useState<ThreadSummary[] | null>(null);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;

    setLoading(true);
    setErrorMessage(null);

    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (cancelled) return;
        setThreads(result.threads);
        setTotal(result.total);
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setThreads(null);
        setTotal(0);
        setErrorMessage(describeError(error));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  function handleSearchSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSearch(searchDraft.trim());
    setPage(1);
  }

  const totalPages = pageCount(total);
  const pages = Array.from({ length: totalPages }, (_, i) => i + 1);

  let body: ReactNode;
  if (errorMessage !== null) {
    // El banner con role="alert" ya cuenta lo que pasó; no se pinta una lista
    // vacía como si el error fuera "no hay hilos".
    body = null;
  } else if (threads === null || loading) {
    body = (
      <div className={styles.loadingPanel} role="status">
        Cargando hilos…
      </div>
    );
  } else {
    body = (
      <ThreadList
        threads={threads}
        now={now ?? new Date()}
        onOpen={() => {
          // MSG-02 fuera del MVP: el clic no navega a ningún sitio.
        }}
      />
    );
  }

  return (
    <>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.pageTitle}>Hilos</h1>
      <p className={styles.pageSubtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está
        cifrado de extremo a extremo.
      </p>

      {/*
        En el MVP no hay passphrase: las claves viven en memoria de sesión. Se
        muestra el estado E2EE activo sin prometer el botón "Introducir frase de
        seguridad", que no existe en este alcance.
      */}
      <p className={styles.e2eeStatus}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · contenido descifrado localmente
      </p>

      {errorMessage !== null && (
        <div role="alert" className={styles.errorBanner}>
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>No se pudieron cargar los hilos. {errorMessage}</span>
        </div>
      )}

      <div className={styles.actionsBar}>
        <form
          className={styles.searchBox}
          role="search"
          aria-label="Buscar hilos"
          onSubmit={handleSearchSubmit}
        >
          <span className={styles.searchIcon} aria-hidden="true">
            <i className="ti ti-search" />
          </span>
          <input
            className={styles.searchInput}
            type="search"
            value={searchDraft}
            onChange={(e) => setSearchDraft(e.target.value)}
            placeholder="Buscar por nombre de organización..."
          />
        </form>

        <span className={styles.newContact}>
          <button type="button" className={styles.primaryButton} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          <span className={styles.scopeNote} data-testid="directorio-scope">
            El Directorio queda fuera del MVP
          </span>
        </span>

        <span className={styles.pageInfo} data-testid="pag-info">
          {total.toLocaleString('es-ES')} hilos · Página {page} de {totalPages}
        </span>
      </div>

      {body}

      <div className={styles.pagination}>
        <button
          type="button"
          className={`${styles.pageButton} ${styles.pageControl}`}
          onClick={() => setPage(Math.max(1, page - 1))}
          disabled={page <= 1}
          aria-label="Página anterior"
        >
          ‹
        </button>
        {pages.map((pageNumber) => (
          <button
            key={pageNumber}
            type="button"
            className={
              pageNumber === page
                ? `${styles.pageButton} ${styles.pageActive}`
                : styles.pageButton
            }
            onClick={() => setPage(pageNumber)}
            aria-current={pageNumber === page ? 'page' : undefined}
          >
            {pageNumber}
          </button>
        ))}
        <button
          type="button"
          className={`${styles.pageButton} ${styles.pageControl}`}
          onClick={() => setPage(Math.min(totalPages, page + 1))}
          disabled={page >= totalPages}
          aria-label="Página siguiente"
        >
          ›
        </button>
      </div>
    </>
  );
}

