/*
 * Estilos de la lista de hilos de MSG-01.
 *
 * Colores solo vía tokens del design-system. El corpus no trae blanco puro: las
 * cajas que el HTML aprobado pintaba en #FFFFFF usan var(--bw-surface-mist), la
 * superficie clara más cercana que no compite con el Cold White del panel.
 */

/* ---- Lista ---- */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.rowItem {
  border-bottom: 1px solid var(--bw-divider-mist);
  transition: background-color 0.1s;
}

.rowItem:last-child {
  border-bottom: none;
}

.rowItem:hover {
  background: var(--bw-row-hover-tint);
}

/* ---- Fila pulsable ---- */

.rowButton {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 10px;
  row-gap: 4px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.rowButton:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  flex-shrink: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-text-secondary);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.timestamp {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.rowBottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.preview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-text-secondary);
}

/* ---- Badge de estado ---- */

.stateBadge {
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  border: 1px solid transparent;
  white-space: nowrap;
}

.toneNeutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border-color: var(--bw-badge-neutral-border);
}

.toneInfo {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border-color: var(--bw-chip-active-border);
}

.toneWarn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border-color: var(--bw-badge-warning-border);
}

.toneSuccess {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border-color: var(--bw-badge-success-border);
}

.toneClosed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border-color: var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

/* ---- Estado vacío ---- */

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 56px 28px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  text-align: center;
}

.emptyMessage {
  margin: 0;
  max-width: 480px;
  font-size: 14px;
  line-height: 1.7;
  color: var(--bw-text-secondary);
}

.emptyActions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.directoryButton {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  border: none;
  border-radius: 5px;
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  cursor: default;
}

.directoryButton:disabled {
  opacity: 0.55;
  cursor: default;
}

.emptyScope {
  font-size: 11px;
  color: var(--bw-input-placeholder);
}

