import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * Lista de hilos de MSG-01, componente de presentación.
 *
 * Pinta las filas exactamente en el orden que recibe: el orden descendente por
 * `last_item_at` lo decide el servidor (fetchThreadPage), no este componente.
 * No carga datos ni pagina.
 *
 * `now` es inyectable para que los tests no dependan del reloj; si no llega,
 * `relativeTime` usa su propio `new Date()` de respaldo.
 *
 * Cada hilo vive en un `<li>` con su rol implícito `listitem`. La fila es
 * pulsable gracias a un `<button>` DENTRO del `<li>` — nunca con `role` encima,
 * porque un rol explícito sustituiría al implícito y el contrato consulta
 * `listitem` (F-131).
 */

/**
 * Tono del badge → clase CSS del módulo.
 *
 * Con `noUncheckedIndexedAccess` activo, una propiedad de `styles` puede no
 * existir en el fichero .module.css, así que el diccionario es
 * `Record<StateTone, string | undefined>` (F-143). El `?? ''` está en el único
 * punto donde se consume: una clase que falte deja el badge sin adorno, nunca
 * escribe la palabra "undefined" en el atributo.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: 'toneNeutral',
  info: 'toneInfo',
  warn: 'toneWarn',
  success: 'toneSuccess',
  closed: 'toneClosed',
};

interface ThreadListProps {
  threads: ThreadSummary[];
  now?: Date | undefined;
  /** Se avisa con el ID del hilo, no con el objeto (F-131). */
  onOpen: (id: string) => void;
}

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    // F-141: el estado vacío no puede ir dentro de un <ul>: con threads vacío
    // el contrato exige que NO quede ningún listitem en el documento.
    return (
      <div className={styles.emptyState}>
        <p className={styles.emptyMessage}>
          Todavía no tienes ninguna conversación. Usa el Directorio para
          contactar con otras organizaciones.
        </p>
        <span className={styles.emptyActions}>
          <button type="button" className={styles.directoryButton} disabled>
            Ir al Directorio
          </button>
          <span className={styles.emptyScope}>
            El Directorio queda fuera del MVP
          </span>
        </span>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)] ?? '';
        return (
          <li key={thread.id} className={styles.rowItem}>
            <button
              type="button"
              className={styles.rowButton}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>
                    {thread.counterpartyCountry}
                  </span>
                ) : null}
              </span>
              <span className={styles.timestamp}>
                {relativeTime(thread.lastItemAt, now)}
              </span>
              <span className={styles.rowBottom}>
                <span className={styles.preview}>
                  {previewLabel(thread.lastItem)}
                </span>
                <span className={`${styles.stateBadge} ${toneClass}`}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
